using System;
using System.Collections.Generic;
public class Archive { public static void Main(string[] args) { var entries = new List<string> { "archive", "document" }; foreach (var entry in entries) { Console.WriteLine(entry); } } }

from pathlib import Path
from typing import Iterable
def restore_archive(entries: Iterable[str]) -> str:
    return "\n".join(entries)
if __name__ == "__main__":
    for entry in ["archive", "document"]:
        print(restore_archive([entry]))

class Archive
  attr_reader :entries
  def initialize(entries)
    @entries = entries
  end
  def restore
    @entries.map { |entry| entry.to_s }.join("\n")
  end
end
puts Archive.new(["archive", "document"]).restore

use std::collections::HashMap;
pub fn restore_archive(entries: &[(&str, &str)]) -> HashMap<String, String> { entries.iter().map(|(id, content)| (id.to_string(), content.to_string())).collect() }
fn main() { println!("{:?}", restore_archive(&[("archive", "document")])); }
